package net.civeira.phylax.feature.identity.consentpurpose.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.consentpurpose.domain.ConsentPurpose;
import net.civeira.phylax.feature.identity.consentpurpose.domain.valueobject.RequiredVO;

class RequiredValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of required of consent purpose")
  void test_required_value_holder_assign_plain_value() {
    Object holder = new Object();
    RequiredValueHolder<Object> value = new RequiredValueHolder<>(holder);
    Assertions.assertSame(holder, value.required(true), "Setters must return the holder");
    Assertions.assertTrue(value.getRequiredValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(true, value.getRequired().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of required of consent purpose")
  void test_required_value_holder_assign_value_object() {
    Object holder = new Object();
    RequiredValueHolder<Object> value = new RequiredValueHolder<>(holder);
    RequiredVO vo = RequiredVO.from(true);
    Assertions.assertFalse(value.getRequiredValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.required(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRequiredValue().orElseThrow());
    Assertions.assertSame(holder, value.required(Optional.empty()));
    Assertions.assertFalse(value.getRequiredValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.required(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRequiredValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of required of consent purpose against the original")
  void test_required_value_holder_read() {
    Object holder = new Object();
    RequiredValueHolder<Object> value = new RequiredValueHolder<>(holder);
    RequiredVO vo = RequiredVO.from(true);
    RequiredVO other = RequiredVO.from(true);
    ConsentPurpose original = Mockito.mock(ConsentPurpose.class);
    Mockito.when(original.getRequiredValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRequired(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRequired(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.required(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRequired(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRequired(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of required of consent purpose")
  void test_required_value_holder_unset() {
    Object holder = new Object();
    RequiredValueHolder<Object> value = new RequiredValueHolder<>(holder);
    RequiredVO vo = RequiredVO.from(true);
    value.required(vo);
    Assertions.assertSame(holder, value.unsetRequiredIfMatches("required_other"));
    Assertions.assertTrue(value.getRequiredValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRequiredIfMatches("required"));
    Assertions.assertFalse(value.getRequiredValue().isPresent(),
        "The field name must clear the value");
    value.required(vo);
    Assertions.assertSame(holder, value.unsetRequired());
    Assertions.assertFalse(value.getRequiredValue().isPresent(), "Unset must clear the value");
  }
}
